starterCodeJson.code:
// Question 1 — the cover page of the SRS template (Wiegers): fill every field, remove every <placeholder>.
const COVER = {
  title: 'Software Requirements Specification',
  project: '<Project name>',
  version: '<1.0>',
  preparedBy: '<Your full name - Student ID>',
  organization: '<Organization>',
  dateCreated: '<yyyy-mm-dd>',
};

// Question 2 — context diagram as a Mermaid flowchart (paste into https://mermaid.live to see it).
// The system = ONE circle. External entities = rectangles. One labelled arrow per direction; label = the DATA.
const CONTEXT_DIAGRAM = `
flowchart LR
  S((System name))
  E1[External entity] -->|data in| S
  S -->|data out| E1
`;

// Question 3 — use case diagram (PlantUML: paste into https://www.plantuml.com/plantuml) + the two tables of the template.
const USE_CASE_DIAGRAM = `
@startuml
left to right direction
actor "Actor name" as A1
rectangle "System name" {
  usecase "Verb Object" as UC1
}
A1 --> UC1
@enduml
`;

// Table "# | Actor | Description" — one object per actor of the diagram (same names).
const ACTORS = [
  { name: 'Actor name', description: '' },
];

// Table "# | Use Case | Actors | Description" — one object per use case (same names as the diagram).
const USE_CASES = [
  { id: 'UC-01', name: 'Verb Object', actors: ['Actor name'], description: '' },
];

// Question 4 — conceptual ERD (Mermaid erDiagram) + the entity table of the template.
const ERD = `
erDiagram
  ENTITY_A ||--o{ ENTITY_B : verb
  ENTITY_A {
    string entityAId PK
    string name
  }
`;

// Table "# | Entity | Description" (+ key attributes) — one object per entity of the ERD.
const ENTITIES = [
  { name: 'ENTITY_A', description: '', attributes: ['entityAId'] },
];

solutionCodeJson.code:
// Question 1 — copy the system name EXACTLY from the paper; the grader cannot know your name, any real one passes.
const COVER = {
  title: 'Software Requirements Specification',
  project: 'GreenRide Campus E-Scooter Sharing',
  version: '1.0',
  preparedBy: 'Nguyen Van An - SE180123',
  organization: 'FPT University, Ho Chi Minh City campus',
  dateCreated: '2026-11-05',
};

// Question 3 — use case diagram consistent with Question 2 (same actors), plus the actor and use case tables.
const USE_CASE_DIAGRAM = `@startuml
left to right direction
actor Rider
actor "Maintenance Technician" as TE
actor "Fleet Manager" as FM
actor "Campus SSO" as SSO
actor "Campus E-wallet" as EW
actor "Scooter Fleet Gateway" as FG
actor "Notification Service" as NS
rectangle "GreenRide Campus E-Scooter Sharing" {
  usecase "Sign In" as UC1
  usecase "Accept Safety Rules" as UC2
  usecase "Find Available Scooter" as UC3
  usecase "Start Ride" as UC4
  usecase "End Ride" as UC5
  usecase "Calculate Ride Cost" as UC6
  usecase "Pay for Ride" as UC7
  usecase "Buy Monthly Pass" as UC8
  usecase "Report Scooter Problem" as UC9
  usecase "Handle Maintenance Ticket" as UC10
  usecase "Manage Stations and Zones" as UC11
  usecase "Set Zone Prices" as UC12
  usecase "View Usage Report" as UC13
  usecase "Send Notification" as UC14
}
Rider --> UC1
TE --> UC1
FM --> UC1
UC1 --> SSO
UC2 ..> UC4 : <<extend>>
Rider --> UC3
Rider --> UC4
UC4 --> FG
Rider --> UC5
UC5 --> FG
UC5 ..> UC6 : <<include>>
UC7 ..> UC5 : <<extend>>
UC7 --> EW
Rider --> UC8
UC8 --> EW
Rider --> UC9
TE --> UC10
FM --> UC11
FM --> UC12
FM --> UC13
UC8 ..> UC14 : <<include>>
UC14 --> NS
@enduml
`;

const ACTORS = [
  {
    name: 'Rider',
    description: 'A student or staff member who finds a scooter, starts and ends rides, buys passes and reports scooter problems.',
  },
  {
    name: 'Maintenance Technician',
    description: 'Staff who handle maintenance tickets for scooters and record the actions taken.',
  },
  {
    name: 'Fleet Manager',
    description: 'Manages docking stations, zones and per-minute prices and reads the monthly usage reports.',
  },
  {
    name: 'Campus SSO',
    description: 'External university sign-on service that authenticates users and returns an identity token.',
  },
  {
    name: 'Campus E-wallet',
    description: 'External payment service that charges riders for single rides and monthly passes.',
  },
  {
    name: 'Scooter Fleet Gateway',
    description: 'External gateway that relays unlock commands to scooters and reports their status and dock events.',
  },
  {
    name: 'Notification Service',
    description: 'External university service that e-mails receipts and pass-expiry reminders.',
  },
];

const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Sign In',
    actors: ['Rider', 'Maintenance Technician', 'Fleet Manager', 'Campus SSO'],
    description: 'A user signs in with the university account through Campus SSO.',
  },
  {
    id: 'UC-02',
    name: 'Accept Safety Rules',
    actors: [],
    description: 'Extension of starting a ride: before the first ride only, the rider accepts the safety rules.',
  },
  {
    id: 'UC-03',
    name: 'Find Available Scooter',
    actors: ['Rider'],
    description: 'The rider sees stations with available scooters and their battery levels.',
  },
  {
    id: 'UC-04',
    name: 'Start Ride',
    actors: ['Rider', 'Scooter Fleet Gateway'],
    description: 'The rider unlocks a scooter at a station; the gateway opens the lock.',
  },
  {
    id: 'UC-05',
    name: 'End Ride',
    actors: ['Rider', 'Scooter Fleet Gateway'],
    description: 'The rider docks the scooter at a station; the gateway reports the dock event.',
  },
  {
    id: 'UC-06',
    name: 'Calculate Ride Cost',
    actors: [],
    description: 'Included in ending every ride: the cost is computed from the minutes, the zone price and any valid pass.',
  },
  {
    id: 'UC-07',
    name: 'Pay for Ride',
    actors: ['Campus E-wallet'],
    description: 'Extension of ending a ride that no valid pass covers: the cost is charged to the e-wallet.',
  },
  {
    id: 'UC-08',
    name: 'Buy Monthly Pass',
    actors: ['Rider', 'Campus E-wallet'],
    description: 'The rider buys a monthly pass and pays through the e-wallet.',
  },
  {
    id: 'UC-09',
    name: 'Report Scooter Problem',
    actors: ['Rider'],
    description: 'The rider reports a problem with a scooter, which opens a maintenance ticket.',
  },
  {
    id: 'UC-10',
    name: 'Handle Maintenance Ticket',
    actors: ['Maintenance Technician'],
    description: 'The technician works on a ticket, records actions and closes it.',
  },
  {
    id: 'UC-11',
    name: 'Manage Stations and Zones',
    actors: ['Fleet Manager'],
    description: 'The fleet manager adds or changes docking stations and the zones they belong to.',
  },
  {
    id: 'UC-12',
    name: 'Set Zone Prices',
    actors: ['Fleet Manager'],
    description: 'The fleet manager sets the price per minute of each zone.',
  },
  {
    id: 'UC-13',
    name: 'View Usage Report',
    actors: ['Fleet Manager'],
    description: 'The fleet manager reads monthly rides, minutes, revenue and scooter availability.',
  },
  {
    id: 'UC-14',
    name: 'Send Notification',
    actors: ['Notification Service'],
    description: 'Included when a receipt or reminder must be e-mailed through the notification service.',
  },
];

// Question 4 — conceptual ERD: identifiers + key attributes, cardinality on both ends, verb labels, no foreign keys.
const ERD = `erDiagram
  RIDER ||--o{ RIDE : takes
  SCOOTER ||--o{ RIDE : "is used in"
  STATION ||--o{ RIDE : "is start of"
  STATION ||--o{ RIDE : "is end of"
  ZONE ||--o{ STATION : contains
  STATION |o--o{ SCOOTER : docks
  RIDER ||--o{ PASS : buys
  PASS |o--o{ RIDE : covers
  RIDE ||--o| PAYMENT : "is paid by"
  PASS ||--|| PAYMENT : "is paid by"
  SCOOTER ||--o{ MAINTENANCE_TICKET : "is subject of"
  TECHNICIAN ||--o{ MAINTENANCE_TICKET : handles
  RIDER |o--o{ MAINTENANCE_TICKET : reports
  RIDER {
    string riderId PK
    string fullName
    date safetyAcceptedOn
  }
  SCOOTER {
    string serialNumber PK
    string model
    int batteryLevel
    string status
  }
  STATION {
    string stationCode PK
    string name
    string location
    int docks
  }
  ZONE {
    string zoneCode PK
    string name
    decimal pricePerMinute
  }
  RIDE {
    string rideId PK
    datetime startTime
    datetime endTime
    decimal distanceKm
    decimal cost
  }
  PASS {
    string passId PK
    string passType
    date startDate
    date endDate
    int includedMinutes
  }
  PAYMENT {
    string paymentId PK
    decimal amount
    datetime paidAt
  }
  MAINTENANCE_TICKET {
    string ticketId PK
    string problem
    string actions
    datetime closedAt
  }
  TECHNICIAN {
    string technicianId PK
    string fullName
  }
`;

const ENTITIES = [
  {
    name: 'RIDER',
    description: 'A student or staff member who rents scooters; keeps the date the safety rules were accepted.',
    attributes: ['riderId', 'fullName', 'safetyAcceptedOn'],
  },
  {
    name: 'SCOOTER',
    description: 'One physical e-scooter identified by its serial number, with model, battery level and status.',
    attributes: ['serialNumber', 'model', 'batteryLevel', 'status'],
  },
  {
    name: 'STATION',
    description: 'A docking station with a code, name, location and number of docks; belongs to one zone.',
    attributes: ['stationCode', 'name', 'location', 'docks'],
  },
  {
    name: 'ZONE',
    description: 'An area of the campus with its own price per minute; contains several stations.',
    attributes: ['zoneCode', 'name', 'pricePerMinute'],
  },
  {
    name: 'RIDE',
    description: 'One rental of one scooter by one rider, from a start station to an end station, with times, distance and cost.',
    attributes: ['rideId', 'startTime', 'endTime', 'distanceKm', 'cost'],
  },
  {
    name: 'PASS',
    description: 'A monthly pass bought by a rider, with type, validity dates and included minutes; may cover several rides.',
    attributes: ['passId', 'passType', 'startDate', 'endDate', 'includedMinutes'],
  },
  {
    name: 'PAYMENT',
    description: 'A charge through the e-wallet that pays for exactly one ride or one pass.',
    attributes: ['paymentId', 'amount', 'paidAt'],
  },
  {
    name: 'MAINTENANCE_TICKET',
    description: 'A record of a problem with one scooter, reported by a rider or opened by a technician, and its resolution.',
    attributes: ['ticketId', 'problem', 'actions', 'closedAt'],
  },
  {
    name: 'TECHNICIAN',
    description: 'A maintenance technician who handles maintenance tickets.',
    attributes: ['technicianId', 'fullName'],
  },
];

